"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["90773"],{48772(e){e.exports=JSON.parse('{"id":"FUT-0361","slug":"systematic-risk","term":"Systematic Risk","also_known_as":["Market Risk"],"difficulty":"Intermediate","definition":"Systematic risk is the risk that affects the whole market or economy, such as a recession, rising interest rates or a financial crisis. It cannot be removed by diversifying.","explanation":["Investment risk comes in two broad kinds. Unsystematic risk is specific to a single company or industry, such as a failed product, a lawsuit or a factory fire. It can be greatly reduced by holding many different investments. Systematic risk affects almost all investments at the same time, so spreading money across more shares does not help much.","Examples of systematic risk include economic recessions, sudden changes in interest rates, high inflation, political crises, wars and pandemics. When a severe recession hits, most share prices tend to fall together.","For example, a portfolio of 500 different companies is well protected if one of them goes bankrupt. But if the whole stock market falls by 30%, that diversified portfolio will still fall by a similar amount.","Because systematic risk cannot be diversified away, investors expect to be paid for bearing it. In models such as the Capital Asset Pricing Model, an asset\'s exposure to systematic risk, measured by its beta, determines its expected return. Investors can reduce systematic risk only by changing their mix of asset types, for example by holding more bonds or cash."],"note":"","total":1500,"prev":{"slug":"synergy","term":"Synergy"},"next":{"slug":"systemically-important-bank","term":"Systemically Important Bank"}}')}}]);